import Foundation
@MainActor public protocol BackupBridgeProtocol: AnyObject { var onChanged: (() -> Void)? { get set }; var onBackupCompleted: ((Bool, String) -> Void)? { get set }; var onRestoreCompleted: ((Bool, String) -> Void)? { get set }; var onRestoreStarted: (() -> Void)? { get set }; func autoBackupEnabled() -> Bool; func setAutoBackupEnabled(_ value: Bool) throws; func snapshot() -> (lastBackupTimeIso: String, busy: Bool, operationBlocksUI: Bool, operationText: String); func requestBackup(path: String); func requestBackupInfo(path: String); func requestRestore(path: String); func readBackupInfo(path: String) -> [String: Any]; func readBackups() throws -> [[String: Any]]; func suggestedBackupFileName() -> String; func backupFileExtension() -> String }
